CREATE TABLE analysis_versions (version_id TEXT PRIMARY KEY, project_id TEXT NOT NULL, analysis_id TEXT NOT NULL, parent_version_id TEXT NOT NULL, evidence_version_id TEXT NOT NULL REFERENCES evidence_versions(version_id), related_version_id TEXT REFERENCES analysis_versions(version_id), stage TEXT NOT NULL CHECK(stage IN ('PLAN','RESULT','APPROVED')), plan_sha256 TEXT NOT NULL, source_job_id TEXT REFERENCES jobs(id), actor_id TEXT NOT NULL REFERENCES app_users(id), created_at TEXT NOT NULL, FOREIGN KEY(version_id,project_id) REFERENCES project_versions(id,project_id), FOREIGN KEY(parent_version_id,project_id) REFERENCES project_versions(id,project_id), FOREIGN KEY(evidence_version_id,project_id) REFERENCES project_versions(id,project_id));
